using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their significance." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds three patents in neural network architectures.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Miller", Title = "Associate Professor of Mathematics", Bio = "Dr. Miller's research focuses on algebraic topology and its applications to data science. He received the Distinguished Teaching Award in 2023.", Email = "j.miller@university.edu" },
            new() { Id = 3, Name = "Dr. Maria Rodriguez", Title = "Professor of Physics", Bio = "Dr. Rodriguez leads the Quantum Computing Lab and has been instrumental in developing new qubit stabilization techniques.", Email = "m.rodriguez@university.edu" },
            new() { Id = 4, Name = "Dr. David Park", Title = "Associate Professor of Computer Science", Bio = "Dr. Park specializes in distributed systems and cloud computing. Previously a senior engineer at a major tech company.", Email = "d.park@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Watson", Title = "Professor of English", Bio = "Dr. Watson is an award-winning author and literary critic specializing in contemporary American fiction.", Email = "e.watson@university.edu" },
            new() { Id = 6, Name = "Dr. Robert Kim", Title = "Associate Professor of History", Bio = "Dr. Kim researches the intersection of technology and society in 20th-century America.", Email = "r.kim@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Tech Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Room = "Tech Hall 305", DepartmentId = 1, InstructorId = 4, IsFeatured = true },
            new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational database systems. Covers SQL, normalization, indexing, transaction processing, and introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Room = "Tech Hall 102", DepartmentId = 1, InstructorId = 4, IsFeatured = false },
            new() { Id = 4, CourseCode = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning algorithms including supervised and unsupervised learning, neural networks, and deep learning frameworks.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", Room = "Tech Hall 401", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 5, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Science Bldg 110", DepartmentId = 2, InstructorId = 2, IsFeatured = false },
            new() { Id = 6, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to computer science and data analysis.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Science Bldg 215", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 7, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Physics Lab 100", DepartmentId = 3, InstructorId = 3, IsFeatured = false },
            new() { Id = 8, CourseCode = "PHYS 320", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, and applications to atomic physics.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Physics Lab 302", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 9, CourseCode = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop effective academic writing skills through essay composition, research methods, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Humanities 205", DepartmentId = 4, InstructorId = 5, IsFeatured = false },
            new() { Id = 10, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present. Explores themes of identity, democracy, and the American experience.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Humanities 310", DepartmentId = 4, InstructorId = 5, IsFeatured = false },
            new() { Id = 11, CourseCode = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from ancient times to 1500 CE. Covers major political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", Room = "Humanities 105", DepartmentId = 5, InstructorId = 6, IsFeatured = false },
            new() { Id = 12, CourseCode = "HIST 340", Title = "Technology & Society", Description = "Examines how technological innovations have shaped social, economic, and political structures from the Industrial Revolution to the digital age.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Room = "Humanities 220", DepartmentId = 5, InstructorId = 6, IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public Department? GetDepartmentForCourse(int courseId)
    {
        var course = GetCourse(courseId);
        return course != null ? GetDepartment(course.DepartmentId) : null;
    }

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

