arguments.file_text:
@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="hero">
    <h1>University Course Catalog</h1>
    <p class="lead">Explore our courses and find the right fit for your academic journey.</p>
    <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
</div>

<section class="mt-5">
    <h2>Featured Courses</h2>
    <div class="row mt-3">
        @foreach (var course in featuredCourses)
        {
            var dept = Catalog.GetDepartmentForCourse(course.Id);
            <div class="col-md-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                        <p class="card-text">@course.Description[..Math.Min(100, course.Description.Length)]...</p>
                        <span class="badge bg-secondary">@dept?.Code</span>
                        <span class="badge bg-info">@course.Credits Credits</span>
                    </div>
                    <div class="card-footer">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section class="mt-5">
    <h2>Departments</h2>
    <div class="row mt-3">
        @foreach (var dept in departments)
        {
            <div class="col-md-4 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text text-muted">@dept.Description</p>
                        <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">View Courses</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<h1>Course Catalog</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses..."
               @bind="searchTerm" @bind:event="oninput" @bind:after="FilterCourses" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId" @bind:after="FilterCourses">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

<p class="text-muted">Showing @filteredCourses.Count course(s)</p>

<div class="table-responsive">
    <table class="table table-hover">
        <thead class="table-light">
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in filteredCourses)
            {
                var dept = Catalog.GetDepartmentForCourse(course.Id);
                <tr>
                    <td><strong>@course.CourseCode</strong></td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();
    private string searchTerm = "";
    private int selectedDepartmentId;

    [SupplyParameterFromQuery]
    public int? departmentId { get; set; }

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        if (departmentId.HasValue)
            selectedDepartmentId = departmentId.Value;
        FilterCourses();
    }

    private void FilterCourses()
    {
        filteredCourses = Catalog.SearchCourses(
            string.IsNullOrWhiteSpace(searchTerm) ? null : searchTerm,
            selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }

    private void ClearFilters()
    {
        searchTerm = "";
        selectedDepartmentId = 0;
        FilterCourses();
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course") - Course Catalog</PageTitle>

@if (course == null)
{
    <h2>Course Not Found</h2>
    <p>The requested course does not exist.</p>
    <a href="/courses" class="btn btn-primary">Back to Catalog</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active">@course.CourseCode</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-md-8">
            <h1>@course.CourseCode: @course.Title</h1>

            <div class="mb-3">
                <span class="badge bg-primary fs-6">@course.Credits Credits</span>
                <span class="badge bg-secondary fs-6">@department?.Name</span>
            </div>

            <section class="mb-4">
                <h3>Description</h3>
                <p>@course.Description</p>
            </section>

            <section class="mb-4">
                <h3>Schedule & Location</h3>
                <table class="table table-bordered w-auto">
                    <tr>
                        <th>Schedule</th>
                        <td>@course.Schedule</td>
                    </tr>
                    <tr>
                        <th>Room</th>
                        <td>@course.Room</td>
                    </tr>
                    <tr>
                        <th>Credits</th>
                        <td>@course.Credits</td>
                    </tr>
                </table>
            </section>

