@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<h1>Course Catalog</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses..."
               @bind="searchTerm" @bind:event="oninput" @bind:after="FilterCourses" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId" @bind:after="FilterCourses">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

<p class="text-muted">Showing @filteredCourses.Count course(s)</p>

<div class="table-responsive">
    <table class="table table-hover">
        <thead class="table-light">
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in filteredCourses)
            {
                var dept = Catalog.GetDepartmentForCourse(course.Id);
                <tr>
                    <td><strong>@course.CourseCode</strong></td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();
    private string searchTerm = "";
    private int selectedDepartmentId;

    [SupplyParameterFromQuery]
    public int? departmentId { get; set; }

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        if (departmentId.HasValue)
            selectedDepartmentId = departmentId.Value;
        FilterCourses();
    }

    private void FilterCourses()
    {
        filteredCourses = Catalog.SearchCourses(
            string.IsNullOrWhiteSpace(searchTerm) ? null : searchTerm,
            selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }

    private void ClearFilters()
    {
        searchTerm = "";
        selectedDepartmentId = 0;
        FilterCourses();
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course") - Course Catalog</PageTitle>

@if (course == null)
{
    <h2>Course Not Found</h2>
    <p>The requested course does not exist.</p>
    <a href="/courses" class="btn btn-primary">Back to Catalog</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active">@course.CourseCode</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-md-8">
            <h1>@course.CourseCode: @course.Title</h1>

            <div class="mb-3">
                <span class="badge bg-primary fs-6">@course.Credits Credits</span>
                <span class="badge bg-secondary fs-6">@department?.Name</span>
            </div>

            <section class="mb-4">
                <h3>Description</h3>
                <p>@course.Description</p>
            </section>

            <section class="mb-4">
                <h3>Schedule & Location</h3>
                <table class="table table-bordered w-auto">
                    <tr>
                        <th>Schedule</th>
                        <td>@course.Schedule</td>
                    </tr>
                    <tr>
                        <th>Room</th>
                        <td>@course.Room</td>
                    </tr>
                    <tr>
                        <th>Credits</th>
                        <td>@course.Credits</td>
                    </tr>
                </table>
            </section>

            @if (instructor != null)
            {
                <section class="mb-4">
                    <h3>Instructor</h3>
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@instructor.Name</h5>
                            <h6 class="card-subtitle mb-2 text-muted">@instructor.Title</h6>
                            <p class="card-text">@instructor.Bio</p>
                            <p class="card-text"><small class="text-muted">Contact: @instructor.Email</small></p>
                        </div>
                    </div>
                </section>
            }
        </div>

        <div class="col-md-4">
            <div class="card bg-light">
                <div class="card-body text-center">
                    <h5 class="card-title">Interested in this course?</h5>
                    <p class="card-text">Submit an enrollment request to reserve your spot.</p>
                    <a href="/enroll?courseId=@course.Id" class="btn btn-success btn-lg">Enroll Now</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Instructor? instructor;
    private Department? department;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course != null)
        {
            instructor = Catalog.GetInstructor(course.InstructorId);
            department = Catalog.GetDepartment(course.DepartmentId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request - Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted Successfully!</h4>
        <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for
            <strong>@selectedCourse?.Title</strong> has been received.</p>
        <p>You will receive a confirmation at your university email within 2 business days.</p>
    </div>
    <a href="/courses" class="btn btn-primary">Back to Course Catalog</a>
}
else
{
    <p class="text-muted">Fill out the form below to submit an enrollment request. All fields are required.</p>

    <form method="post" @onsubmit="HandleSubmit" @formname="enrollment">
        <AntiforgeryToken />

        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName" name="model.StudentName"
                           @bind="model.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="model.StudentId"
                           @bind="model.StudentId" required placeholder="e.g., STU-12345" />
                </div>

                <div class="mb-3">
                    <label for="courseSelect" class="form-label">Course</label>
                    <select class="form-select" id="courseSelect" name="model.CourseId"
                            @bind="model.CourseId" required>
                        <option value="0" disabled>Select a course...</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.CourseCode - @course.Title</option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </div>
    </form>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? courseId { get; set; }

    private List<Course> courses = new();
    private Course? selectedCourse;
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();
        if (courseId.HasValue && model.CourseId == 0)
            model.CourseId = courseId.Value;
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(model.StudentName) ||
            string.IsNullOrWhiteSpace(model.StudentId) ||
            model.CourseId == 0)
            return;

        selectedCourse = Catalog.GetCourse(model.CourseId);
        Catalog.SubmitEnrollment(model);
        submitted = true;
    }
}

